# Code generated by Claude
"""Rate limiting of joint targets, so that a resumed policy cannot make the arm jump (snap-back safety).

    q = rate_limit(current, goal, max_speed, dt)

Returns the targets one tick of `dt` seconds toward `goal`, starting from `current`, so that no joint moves faster than `max_speed` (radians
per second for arm joints; metres per second for a finger travel). If the goal is within reach it is returned unchanged (exactly), so a policy
that always commands through this keeps its normal behaviour whenever it is already close to where it left off. If not (the operator moved the
arm while the policy was paused) the step is the straight line in joint space toward the goal, scaled so the fastest joint moves
`max_speed * dt`; the arm then glides back instead of jumping.

A policy calls it with the arm's CURRENT APPLIED targets (obs["applied"]["arm_targets"][side]) as `current`, not with its own last command.
"""

import numpy as np


def rate_limit(current, goal, max_speed, dt):
    """Moves joint targets from `current` toward `goal` by at most one tick of limited speed.

    Args:
        current (array-like of float): Targets the joints are at now, one value per joint (radians for arm joints, metres for a finger travel).
        goal (array-like of float): Targets the caller wants, same length as `current`.
        max_speed (float): Largest speed any one joint may move at, in radians per second (metres per second for a finger travel).
        dt (float): Length of the tick in seconds.

    Returns:
        numpy.ndarray: The new targets, a float array. It is `goal` itself (as a float array) when the largest joint difference is at most
        `max_speed * dt`; otherwise it is `current` plus the difference to `goal`, scaled so that the joint with the largest difference moves
        exactly `max_speed * dt` and the others move proportionally less.
    """
    current = np.asarray(current, float)
    goal = np.asarray(goal, float)
    delta = goal - current
    biggest = float(np.abs(delta).max()) if delta.size else 0.0
    step = max_speed * dt
    if biggest <= step:
        return goal
    return current + delta * (step / biggest)
